let f=await frame('generator-sharing');await open(f);await f.locator('[name=slip]').fill('0.35');await f.evaluate(()=>MT_STUDY_DRAFT.flush());await p.reload();await p.waitForFunction(()=>window.MT_INTERACTIVE_MODULES?.length===53);f=await frame('generator-sharing');assert.equal(await f.locator('[name=slip]').inputValue(),'0.35');assert.deepEqual(errors,[]);console.log(JSON.stringify({status:'PASS',engine,checks,modules:8,scope:'Builder save/import/export, invalid states, decimals and EN/NB; eight module learning cycles, 24 tasks, every chart on four widths, 32 exports and model draft restoration.'}));
